const result = { framework: await page.evaluate(() => window.bench.framework), started: new Date().toISOString(), checks: [] };
const settle = () => page.evaluate(() => window.bench.settle());
const mount = (id) => page.evaluate(async (component) => { await window.bench.unmount(); await window.bench.mount(component, 1); }, id);
const focus = () => page.evaluate(() => ({ tag: document.activeElement?.tagName, class: document.activeElement?.className, text: document.activeElement?.textContent?.trim().slice(0, 80) }));

await mount('toggle-button');
const toggle = page.locator('.so-toggle-button');
const initialPressed = await toggle.getAttribute('aria-pressed');
await toggle.press('Enter'); await settle();
const afterEnter = await toggle.getAttribute('aria-pressed');
await toggle.press('Space'); await settle();
result.checks.push({ component: 'ToggleButton', initialPressed, afterEnter, afterSpace: await toggle.getAttribute('aria-pressed'), type: await toggle.getAttribute('type') });

await mount('toggle-group');
const items = page.locator('.so-toggle-group-item');
await items.first().press('End'); await settle();
const endFocus = await focus();
await page.keyboard.press('Space'); await settle();
const endPressed = await items.last().getAttribute('aria-pressed');
await page.keyboard.press('Home'); await settle();
result.checks.push({ component: 'ToggleGroup', itemCount: await items.count(), endFocus, endPressed, homeFocus: await focus(), tabStops: await page.evaluate(() => [...document.querySelectorAll('.so-toggle-group-item')].filter(x => x.tabIndex === 0).length) });

await mount('code-block');
const tabs = page.locator('.so-code-block [role="tab"]');
await tabs.first().press('ArrowRight'); await settle();
const second = { selected: await tabs.nth(1).getAttribute('aria-selected'), focus: await focus(), source: await page.locator('.so-code-block [role="region"]').textContent() };
await page.keyboard.press('Home'); await settle();
result.checks.push({ component: 'CodeBlock', second, afterHome: await tabs.first().getAttribute('aria-selected'), homeFocus: await focus() });

await mount('breadcrumbs');
const trigger = page.locator('.so-breadcrumbs__trigger');
const closedControls = await trigger.getAttribute('aria-controls');
const closedReference = await page.evaluate(() => { const t = document.querySelector('.so-breadcrumbs__trigger'); const id = t?.getAttribute('aria-controls'); return { expanded: t?.getAttribute('aria-expanded'), controls: id, resolved: Boolean(id && document.getElementById(id)) }; });
await trigger.press('Enter'); await settle();
const openReference = await page.evaluate(() => { const t = document.querySelector('.so-breadcrumbs__trigger'); const id = t?.getAttribute('aria-controls'); const panel = id ? document.getElementById(id) : null; return { expanded: t?.getAttribute('aria-expanded'), controls: id, resolved: Boolean(panel), panelRole: panel?.getAttribute('role'), panelOpen: panel?.getAttribute('data-open') }; });
await page.keyboard.press('End'); await settle();
const endMenu = await focus();
await page.keyboard.press('Home'); await settle();
const homeMenu = await focus();
await page.keyboard.press('Escape'); await settle();
result.checks.push({ component: 'Breadcrumbs', closedControls, closedReference, openReference, endMenu, homeMenu, closedExpanded: await trigger.getAttribute('aria-expanded'), finalFocus: await focus(), triggerFocused: await page.evaluate(() => document.activeElement === document.querySelector('.so-breadcrumbs__trigger')), openMenus: await page.locator('.so-menu__panel[data-open="true"]').count() });

await mount('alert-dialog');
const opener = page.locator('.bench-page .so-button').first();
await opener.press('Enter'); await settle();
const initialDialog = await page.evaluate(() => { const p = document.querySelector('.so-alert-dialog[data-open="true"]'); return { role: p?.getAttribute('role'), modal: p?.getAttribute('aria-modal'), safeFocused: document.activeElement?.classList.contains('so-alert-dialog__cancel'), name: document.getElementById(p?.getAttribute('aria-labelledby') ?? '')?.textContent?.trim(), description: document.getElementById(p?.getAttribute('aria-describedby') ?? '')?.textContent?.trim() }; });
const trap = [];
for (const key of ['Shift+Tab','Tab','Tab','Tab','Tab']) { await page.keyboard.press(key); await settle(); trap.push(await page.evaluate(() => Boolean(document.querySelector('.so-alert-dialog[data-open="true"]')?.contains(document.activeElement)))); }
await page.keyboard.press('Escape'); await settle();
result.checks.push({ component: 'AlertDialog', initialDialog, trap, openAfterEscape: await page.locator('.so-alert-dialog[data-open="true"]').count(), openerFocused: await page.evaluate(() => document.activeElement === document.querySelector('.bench-page .so-button')) });

await mount('alert');
await page.locator('.so-alert__close').press('Enter'); await settle();
result.checks.push({ component: 'Alert', visibleAfterClose: await page.locator('.so-alert').isVisible() });

for (const [component, selector] of [['Badge','.so-badge'],['Avatar','.so-avatar'],['Separator','.so-separator']]) {
 await mount(component.toLowerCase());
 result.checks.push(await page.locator(selector).first().evaluate((el, name) => ({ component: name, keyboard: 'N/A: component has no independent keyboard action', role: el.getAttribute('role'), label: el.getAttribute('aria-label'), hidden: el.getAttribute('aria-hidden'), orientation: el.getAttribute('aria-orientation'), text: el.textContent?.trim().slice(0,80) }), component));
}
await page.evaluate(() => window.bench.unmount());
result.finished = new Date().toISOString();
result.environment = await page.evaluate(() => ({ userAgent: navigator.userAgent, platform: navigator.platform }));
return result;
